```c
xmlChar *
xmlEscapeText(const xmlChar *string, int flags) {
    const xmlChar *cur;
    xmlChar *buffer;
    xmlChar *out;
    const signed char *tab;
    size_t size = 50;
    ...
    while (*cur != 0) {
        const xmlChar *base;
        const char *repl;
        size_t used;
        size_t replSize;
        size_t unescapedSize;
        size_t totalSize;
        int c;
        int offset;

        base = cur;
        offset = -1;

        while (1) {
            c = *cur;

            if (c < 0x80) {
                offset = tab[c];
                if (offset >= 0)
                    break;
            } else if (flags & XML_ESCAPE_NON_ASCII) {
                break;
            }

            cur += 1;
        }

        unescapedSize = cur - base;

        if (offset >= 0) {
            if (c == 0) {
                replSize = 0;
                repl = "";
            } else {
                replSize = xmlEscapeContent[offset],
                repl = &xmlEscapeContent[offset+1];
                cur += 1;
            }
        } else {
            char tempBuf[12];
            int val = 0, len = 4;

            val = xmlGetUTF8Char(cur, &len);
            if (val < 0) {
                val = 0xFFFD;
                cur += 1;
            } else {
                if ((val == 0xFFFE) || (val == 0xFFFF))
                    val = 0xFFFD;
                cur += len;
            }

            replSize = xmlSerializeHexCharRef(tempBuf, val);
            repl = tempBuf;   // <-- repl points to tempBuf which is on the stack
        }

        used = out - buffer;
        totalSize = unescapedSize + replSize;

        if (totalSize > size - used) {
            xmlChar *tmp;
            int newSize;

            if ((size > (SIZE_MAX - 1) / 2) ||
                (totalSize > (SIZE_MAX - 1) / 2 - size)) {
                xmlFree(buffer);
                return(NULL);
            }
            newSize = size + totalSize;
            if (*cur != 0)
                newSize *= 2;
            tmp = xmlRealloc(buffer, newSize + 1);
            if (tmp == NULL) {
                xmlFree(buffer);
                return(NULL);
            }
            buffer = tmp;
            size = newSize;
            out = buffer + used;
        }

        memcpy(out, base, unescapedSize);
        out += unescapedSize;
        memcpy(out, repl, replSize);   // <-- reads through stale pointer to tempBuf
        out += replSize;

        if (c == 0)
            break;

        base = cur;
    }
    ...
}
```

So the bug is: when `offset < 0` (i.e., a non-ASCII character that needs to be escaped via `XML_ESCAPE_NON_ASCII`), the code creates a `tempBuf[12]` on the stack, writes the hex char ref into it, and sets `repl = tempBuf`. Then later, `memcpy(out, repl, replSize)` reads from `repl` (which points to `tempBuf`).

But wait, the `tempBuf` is declared inside the `else` block (the `offset < 0` branch). So when the `else` block ends, `tempBuf` goes out of scope. Then `repl` is a dangling pointer. The `memcpy(out, repl, replSize)` happens AFTER the `else` block ends.

Actually, let me re-read. The `tempBuf` is declared inside the `else` block:
